import base64, gzip, hashlib, subprocess, sys
from pathlib import Path
DATA = ''''''
patch = gzip.decompress(base64.b64decode(DATA, validate=True))
assert hashlib.sha256(patch).hexdigest() == '5c115806dd4a0d4f69be99afa821dacab17a1f30ea09bd83419fbb0438d82301'
assert Path('frontend/package.json').exists(), 'Run from repository root'
subprocess.run(['git','apply','--check','-'], input=patch, check=True)
if sys.argv[1:] == ['--apply']:
    subprocess.run(['git','apply','-'], input=patch, check=True)
elif sys.argv[1:]:
    raise SystemExit('Use no arguments for check, or --apply')
